<?php declare(strict_types=1);
require dirname(__DIR__).'/native/bootstrap.php';
use Kulturhus\Native\TestSupport;
use Kulturhus\Native\Shared\{Access,Db};
use Kulturhus\Native\Cms\{Schema,DataModel,ModelCatalogue,Templates};
use Kulturhus\Native\Web\ContentModel;
$db=TestSupport::db();TestSupport::seed($db);Schema::install($db);$access=new Access($db,'admin');$model=new DataModel($db,$access);$catalogue=new ModelCatalogue($db,$access);$checks=0;
function check(bool$okay,string$label):void{global$checks;if(!$okay)throw new RuntimeException($label);++$checks;echo "PASS $label\n";}
function rejects(callable$operation,string$class,string$label):void{try{$operation();}catch(Throwable$error){check($error instanceof$class,$label.' ('.$error::class.')');return;}throw new RuntimeException($label);}
for($i=0;$i<27;$i++)$model->saveField(['key'=>'catalogue_'.sprintf('%02d',$i),'label'=>'Own catalogue '.sprintf('%02d',$i),'type'=>'text']);
$model->saveField(['key'=>'catalogue_wild','label'=>"Own literal 10%_=' catalogue",'type'=>'text']);
for($i=0;$i<13;$i++)$model->saveTemplate(['key'=>'catalogue_template_'.sprintf('%02d',$i),'label'=>'Own template '.sprintf('%02d',$i),'renderer'=>'standard','fields'=>['catalogue_00']]);
$originals=Db::run($db,'SELECT * FROM khcms_definitions ORDER BY club_id,kind,definition_key')->fetchAll();$revisions=Db::run($db,'SELECT * FROM khcms_definition_revisions ORDER BY club_id,kind,definition_key,version')->fetchAll();
$first=$catalogue->listing(['model_q'=>'Own catalogue']);$second=$catalogue->listing(['model_q'=>'Own catalogue','model_page'=>2]);$last=$catalogue->listing(['model_q'=>'Own catalogue','model_page'=>'1000001']);
check($first['total']===27&&count($first['items'])===6&&count($second['items'])===6&&count($last['items'])===3&&$last['model_page']===5,'actual model metadata has matching SQL count and bounded six-entry pages');
check(!array_intersect(array_column($first['items'],'key'),array_column($second['items'],'key')),'model pages retain stable original identities without duplicate rows');
check(array_diff(array_keys($first['items'][0]),['key','label','type','version'])===[],'metadata list returns only bounded summary properties');
$literal=$catalogue->listing(['model_q'=>'10%_=']);check($literal['total']===1&&$literal['items'][0]['key']==='catalogue_wild','search treats wildcard and SQL punctuation literally');
$templates=$catalogue->listing(['model_kind'=>'template']);check($templates['total']===13+count(Templates::all())&&count($templates['items'])===6,'template catalogue counts canonical builtins and custom originals once');
$builtin=$model->template('standard');$builtin=$model->saveTemplate(array_replace($builtin,['label'=>'Own builtin override']),0);$templates=$catalogue->listing(['model_kind'=>'template']);check($templates['total']===13+count(Templates::all())&&$catalogue->selected('template','standard')['label']==='Own builtin override','selected builtin override replaces metadata without adding a second original identity');
$ui=new ContentModel($db,$access,'own-catalogue-csrf');$html=$ui->manager(['model_q'=>'Own catalogue']);check(substr_count($html,'class="model-catalogue-item"')===6&&!str_contains($html,'data-model-form'),'default management renders six metadata rows and no hidden collection of edit forms');
$html=$ui->manager(['model_q'=>'Own catalogue','model_key'=>'catalogue_12']);check(substr_count($html,'data-model-form')===1&&preg_match('/<input[^>]*name="key"[^>]*value="catalogue_12"/',$html)===1&&str_contains($html,'name="version" value="1"'),'selection renders exactly one original field editor with its exact version');
$html=$ui->manager(['model_kind'=>'template','model_q'=>'Own template','model_key'=>'catalogue_template_12']);check(substr_count($html,'data-model-form')===1&&preg_match('/<input[^>]*name="key"[^>]*value="catalogue_template_12"/',$html)===1,'template selection renders only its own original editor');
$html=$ui->manager(['model_new'=>'1']);check(substr_count($html,'data-model-form')===1&&str_contains($html,'name="version" value="0"')&&str_contains($html,'name="model_new" value="1"'),'new model is a separate initial form with a closed preserved list state');
foreach([['model_kind'=>'execute'],['model_q'=>['bad']],['model_page'=>'0'],['model_page'=>'1000002'],['model_key'=>'../foreign'],['model_new'=>'1','model_key'=>'catalogue_00']]as$query)rejects(fn()=>$catalogue->listing($query),InvalidArgumentException::class,'malformed model browse state is rejected');
rejects(fn()=>$catalogue->selected('field','missing_original'),DomainException::class,'known absent original key never selects another definition');
$restricted=$model->saveField(['key'=>'catalogue_role','label'=>'Own protected schema label','type'=>'text','access'=>['read'=>'publish']]);Db::run($db,"INSERT INTO native_users(id,club_id,name) VALUES('catalogue-manager','synthetic-a','Own manager')");foreach(['read','manage']as$cap)Db::run($db,"INSERT INTO native_grants(actor_id,module,capability)VALUES('catalogue-manager','website',?)",[$cap]);$limited=new ModelCatalogue($db,new Access($db,'catalogue-manager'));
check($limited->listing(['model_q'=>'Own protected schema label'])['total']===0,'metadata field restrictions apply before count and limited row selection');rejects(fn()=>$limited->selected('field','catalogue_role'),DomainException::class,'direct model key cannot reveal a forbidden original definition');
Db::run($db,"INSERT INTO native_grants(actor_id,module,capability)VALUES('catalogue-manager','website','publish')");check($limited->listing(['model_q'=>'Own protected schema label'])['total']===1,'existing catalogue immediately reflects a live schema read grant');Db::run($db,"DELETE FROM native_grants WHERE actor_id='catalogue-manager' AND module='website' AND capability='publish'");check($limited->listing(['model_q'=>'Own protected schema label'])['total']===0,'existing catalogue immediately reflects schema grant revocation');
foreach($originals as$row)check(Db::run($db,'SELECT * FROM khcms_definitions WHERE club_id=? AND kind=? AND definition_key=?',[$row['club_id'],$row['kind'],$row['definition_key']])->fetch()===$row,'bounded browsing preserves each exact existing model original');foreach($revisions as$row)check(Db::run($db,'SELECT * FROM khcms_definition_revisions WHERE club_id=? AND kind=? AND definition_key=? AND version=?',[$row['club_id'],$row['kind'],$row['definition_key'],$row['version']])->fetch()===$row,'bounded browsing preserves each exact historical model revision');
echo json_encode(['checks'=>$checks,'live_transport'=>false],JSON_THROW_ON_ERROR)."\n";
